-- Comentarios da Lei 15.040/2024, lote 7 (arts. 121 a 134). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='lei15040' and numero between 121 and 134 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(121,'Pagamento do capital segurado em hipóteses de risco especial','A seguradora não se exime do pagamento do capital segurado, ainda que previsto contratualmente, quando a morte ou a incapacidade decorrer do trabalho, da prestação de serviços militares, de atos humanitários, da utilização de meio de transporte arriscado ou da prática desportiva.'),
(122,'Capital segurado: sub-rogação e impenhorabilidade','Os capitais segurados devidos em razão de morte ou de perda da integridade física não implicam sub-rogação, quando pagos, e são impenhoráveis.'),
(123,'Modificação dos seguros coletivos de vida e integridade física','Nos seguros coletivos sobre a vida e a integridade física, a modificação dos termos do contrato em vigor que possa gerar efeitos contrários aos interesses dos segurados e dos beneficiários dependerá da anuência expressa de segurados que representem pelo menos 3/4 (três quartos) do grupo. O parágrafo único dispõe que, quando não prevista no contrato anterior, a modificação do conteúdo dos seguros coletivos sobre a vida e a integridade física, em caso de renovação, dependerá da anuência expressa de segurados que representem pelo menos 3/4 (três quartos) do grupo.'),
(124,'Recusa de renovação de seguros individuais renovados por mais de dez anos','Salvo se a seguradora encerrar operações no ramo ou na modalidade, a recusa de renovação de seguros individuais sobre a vida e a integridade física que tenham sido renovados sucessiva e automaticamente por mais de 10 (dez) anos deverá ser precedida de comunicação ao segurado e acompanhada de oferta de outro seguro que contenha garantia similar e preços atuarialmente repactuados, em função da realidade e do equilíbrio da carteira, com antecedência mínima de 90 (noventa) dias, vedados carências e direito de recusa de prestação em virtude de fatos preexistentes.'),
(125,'Seguros obrigatórios: conteúdo mínimo e nulidade de renúncia','As garantias dos seguros obrigatórios terão conteúdo e valores mínimos, de modo a permitir o cumprimento de sua função social. O parágrafo único dispõe que é nulo, nos seguros obrigatórios, o negócio jurídico que direta ou indiretamente implique renúncia total ou parcial da indenização ou do capital segurado para os casos de morte ou de invalidez.'),
(126,'Prazos prescricionais','Prescrevem em 1 (um) ano, contado da ciência do respectivo fato gerador (inciso I): a pretensão da seguradora para a cobrança do prêmio ou qualquer outra pretensão contra o segurado e o estipulante do seguro (alínea a); a pretensão dos intervenientes corretores de seguro, agentes ou representantes de seguro e estipulantes para a cobrança de suas remunerações (alínea b); as pretensões das cosseguradoras entre si (alínea c); e as pretensões entre seguradoras, resseguradoras e retrocessionárias (alínea d). Prescreve em 1 (um) ano, contado da ciência da recepção da recusa expressa e motivada da seguradora, a pretensão do segurado para exigir indenização, capital, reserva matemática, prestações vencidas de rendas temporárias ou vitalícias e restituição de prêmio em seu favor (inciso II). Prescreve em 3 (três) anos, contados da ciência do respectivo fato gerador, a pretensão dos beneficiários ou terceiros prejudicados para exigir da seguradora indenização, capital, reserva matemática e prestações vencidas de rendas temporárias ou vitalícias (inciso III).'),
(127,'Suspensão da prescrição por pedido de reconsideração','Além das causas previstas na Lei n. 10.406, de 10 de janeiro de 2002 (Código Civil), a prescrição da pretensão relativa ao recebimento de indenização ou capital segurado será suspensa uma única vez, quando a seguradora receber pedido de reconsideração da recusa de pagamento. O parágrafo único dispõe que cessa a suspensão no dia em que o interessado for comunicado pela seguradora de sua decisão final.'),
(128,'Atos normativos da autoridade fiscalizadora','A autoridade fiscalizadora poderá expedir atos normativos que não contrariem a Lei, atuando para a proteção dos interesses dos segurados e de seus beneficiários.'),
(129,'Meios alternativos de resolução de litígios','Nos contratos de seguro sujeitos à Lei, poderá ser pactuada, mediante instrumento assinado pelas partes, a resolução de litígios por meios alternativos, que será feita no Brasil e submetida às regras do direito brasileiro, inclusive na modalidade de arbitragem. O parágrafo único dispõe que a autoridade fiscalizadora disciplinará a divulgação obrigatória dos conflitos e das decisões respectivas, sem identificações particulares, em repositório de fácil acesso aos interessados.'),
(130,'Competência da justiça brasileira','É absoluta a competência da justiça brasileira para a composição de litígios relativos aos contratos de seguro sujeitos à Lei, sem prejuízo do previsto no art. 129.'),
(131,'Foro competente','O foro competente para as ações de seguro é o do domicílio do segurado ou do beneficiário, salvo se eles ajuizarem a ação optando por qualquer domicílio da seguradora ou de agente dela. O parágrafo único dispõe que a seguradora, a resseguradora e a retrocessionária, para as ações e as arbitragens promovidas entre si, em que sejam discutidos conflitos que possam interferir diretamente na execução dos contratos de seguro sujeitos à Lei, respondem no foro de seu domicílio no Brasil.'),
(132,'Contrato de seguro sobre a vida como título executivo extrajudicial','Os contratos de seguro sobre a vida são títulos executivos extrajudiciais. O parágrafo único dispõe que o título executivo extrajudicial será constituído por qualquer documento que se mostre hábil para a prova da existência do contrato e do qual constem os elementos essenciais para a verificação da certeza e da liquidez da dívida, acompanhado dos documentos necessários à prova de sua exigibilidade.'),
(133,'Revogações','Ficam revogados o inciso II do § 1º do art. 206 e os arts. 757 a 802 da Lei n. 10.406, de 10 de janeiro de 2002 (Código Civil), bem como os arts. 9º a 14 do Decreto-Lei n. 73, de 21 de novembro de 1966. No banco, o Código Civil já consta com esses dispositivos registrados como não vigentes; o Decreto-Lei n. 73, de 1966, não integra o banco.'),
(134,'Vigência','A Lei entra em vigor após decorrido 1 (um) ano de sua publicação oficial.')
) as v(n,c,a)
where l.codigo='lei15040' and l.numero=v.n and l.paragrafo is null and l.inciso is null and l.vigente;
